package net.minecraft.core.registries;import java.util.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.Item;public class BuiltInRegistries{public static final Registry ITEM=new Registry(),ENTITY_TYPE=new Registry(),VILLAGER_PROFESSION=new Registry();public static class Registry implements Iterable<Object>{public Iterator<Object>iterator(){return data.values().iterator();}public Map<String,Object>data=new HashMap<>();public boolean containsKey(ResourceLocation k){return data.containsKey(k.toString());}public Object get(ResourceLocation k){return data.get(k.toString());}public ResourceLocation getKey(Object value){if(value instanceof Item i)return ResourceLocation.parse(i.id());for(var e:data.entrySet())if(e.getValue()==value)return ResourceLocation.parse(e.getKey());throw new IllegalStateException("not registered");}public void item(String id){data.put(id,new Item(id));}}}
